mapper.select:
SELECT COLLECTION_ID,
       CONTENT_ID,
       TO_CHAR(ADDED_DT, 'YYYY-MM-DD HH24:MI:SS') AS ADDED_DT
  FROM COLLECTION_ITEM
 WHERE COLLECTION_ID = #{collectionId}
   AND CONTENT_ID = #{contentId}

mapper.delete:
DELETE FROM COLLECTION_ITEM
 WHERE COLLECTION_ID = #{collectionId}
   AND CONTENT_ID = #{contentId}

mapper.select:
SELECT COLLECTION_ID, CONTENT_ID, ADDED_DT FROM ( SELECT CI.COLLECTION_ID, CI.CONTENT_ID, TO_CHAR(CI.ADDED_DT, 'YYYY-MM-DD HH24:MI:SS') AS ADDED_DT, ROW_NUMBER() OVER ( ORDER BY CI.ADDED_DT DESC, CI.COLLECTION_ID DESC, CI.CONTENT_ID DESC ) AS RNUM FROM COLLECTION_ITEM CI
AND CI.COLLECTION_ID = #{searchWord}
AND CI.CONTENT_ID = #{searchWord}
)
WHERE RNUM BETWEEN ((#{pageNo} - 1) * #{pageSize} + 1) AND (#{pageNo} * #{pageSize})
ORDER BY RNUM
